import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String line = br.readLine(); if (line != null) { StringTokenizer st = new StringTokenizer(line); int x = Integer.parseInt(st.nextToken()); int y = Integer.parseInt(st.nextToken()); System.out.println(x * y); } } }